        "file": "tests/unit.test.tsx",
        "code": "// === FILE: tests/unit.test.tsx ===\nimport React from 'react';\nimport { render, screen, fireEvent } from '@testing-library/react';\nimport { describe, it, expect, vi } from 'vitest';\nimport { DesignSystemStudio, PrimitiveBox } from '../src/DesignSystemStudio';\n\nvi.mock('../src/actions', () => ({\n  updateDesignTokenAction: vi.fn(async (_prev: unknown, formData: FormData) => ({\n    status: 'success',\n    data: {\n      id: 'tok_1',\n      name: String(formData.get('name')),\n      category: 'color',\n      cssVar: '--ds-color-primary',\n      value: String(formData.get('value')),\n      roughness: 0.2,\n      metalness: 0.8,\n    },\n  })),\n}));\n\ndescribe('Project 01: Enterprise Design System & 3D Shader Studio', () => {\n  it('renders polymorphic PrimitiveBox as custom semantic element and switches active tokens', () => {\n    render(\n      <div>\n        <PrimitiveBox as=\"a\" href=\"https://example.com\">\n          Docs Link\n        </PrimitiveBox>\n        <DesignSystemStudio />\n      </div>\n    );\n\n    const link = screen.getByText('Docs Link');\n    expect(link.tagName).toBe('A');\n    expect(screen.getByTestId('optimistic-hex').textContent).toBe('#38bdf8');\n\n    const secondTokenBtn = screen.getByRole('button', { name: 'color.surface.elevated' });\n    fireEvent.click(secondTokenBtn);\n    expect(screen.getByTestId('optimistic-hex').textContent).toBe('#6366f1');\n  });\n});\n\n// === FILE: tests/e2e.spec.ts ===\nimport { test, expect } from '@playwright/test';\n\ntest.describe('Project 01: Enterprise Design System & 3D Shader Studio \u2014 E2E & WCAG 2.2 AAA Verification', () => {\n  test('renders standalone interactive course & 3D telemetry studio without console errors', async ({ page }) => {\n    const errors: string[] = [];\n    page.on('pageerror', (err) => errors.push(err.message));\n    await page.goto('file:///Users/billyribeiro/Desktop/react-enterprise-projects/projects/01-enterprise-design-system/index.html');\n    await expect(page.locator('h1')).toContainText(\"Enterprise Design System & 3D Shader Studio\");\n    await expect(page.locator('.step-card')).toHaveCount(5);\n    expect(errors).toEqual([]);\n  });\n});"
