        "code": "// === FILE: tests/unit.test.tsx ===\nimport React from 'react';\nimport { render, screen, fireEvent } from '@testing-library/react';\nimport { describe, it, expect } from 'vitest';\nimport { EdgeCommerceCheckout } from '../src/EdgeCommerceCheckout';\n\ndescribe('Project 12: Edge-First High-Concurrency Flash Sale Engine', () => {\n  it('decrements inventory atomically and prevents overselling past zero', () => {\n    render(<EdgeCommerceCheckout initialStock={2} />);\n    const btn = screen.getByRole('button');\n    fireEvent.click(btn);\n    expect(screen.getByTestId('stock-remaining').textContent).toBe('1');\n\n    fireEvent.click(btn);\n    expect(screen.getByTestId('stock-remaining').textContent).toBe('0');\n    expect(btn.hasAttribute('disabled')).toBe(true);\n  });\n});\n\n// === FILE: tests/e2e.spec.ts ===\nimport { test, expect } from '@playwright/test';\n\ntest.describe('Project 12: Edge-First High-Concurrency Flash Sale & Inventory Engine \u2014 E2E & WCAG 2.2 AAA Verification', () => {\n  test('renders standalone interactive course & 3D telemetry studio without console errors', async ({ page }) => {\n    const errors: string[] = [];\n    page.on('pageerror', (err) => errors.push(err.message));\n    await page.goto('file:///Users/billyribeiro/Desktop/react-enterprise-projects/projects/12-edge-commerce-checkout/index.html');\n    await expect(page.locator('h1')).toContainText(\"Edge-First High-Concurrency Flash Sale & Inventory Engine\");\n    await expect(page.locator('.step-card')).toHaveCount(5);\n    expect(errors).toEqual([]);\n  });\n});"
