        "code": "// === FILE: tests/unit.test.tsx ===\nimport React from 'react';\nimport { render, screen, fireEvent } from '@testing-library/react';\nimport { describe, it, expect } from 'vitest';\nimport { GlobalI18nCms } from '../src/GlobalI18nCms';\n\ndescribe('Project 18: Global i18n, BiDi RTL Layout & ICU CMS', () => {\n  it('switches dir attribute to rtl and renders Arabic headline when ar-SA is selected', () => {\n    render(<GlobalI18nCms />);\n    expect(screen.getByTestId('bidi-container').getAttribute('dir')).toBe('ltr');\n\n    fireEvent.click(screen.getByRole('button', { name: 'ar-SA' }));\n    expect(screen.getByTestId('bidi-container').getAttribute('dir')).toBe('rtl');\n    expect(screen.getByTestId('localized-headline').textContent).toContain('\u0662\u0660\u0662\u0666');\n  });\n});\n\n// === FILE: tests/e2e.spec.ts ===\nimport { test, expect } from '@playwright/test';\n\ntest.describe('Project 18: Global i18n, BiDi RTL Layout & ICU MessageFormat CMS \u2014 E2E & WCAG 2.2 AAA Verification', () => {\n  test('renders standalone interactive course & 3D telemetry studio without console errors', async ({ page }) => {\n    const errors: string[] = [];\n    page.on('pageerror', (err) => errors.push(err.message));\n    await page.goto('file:///Users/billyribeiro/Desktop/react-enterprise-projects/projects/18-i18n-rtl-global-cms/index.html');\n    await expect(page.locator('h1')).toContainText(\"Global i18n, BiDi RTL Layout & ICU MessageFormat CMS\");\n    await expect(page.locator('.step-card')).toHaveCount(5);\n    expect(errors).toEqual([]);\n  });\n});"
