        "code": "// === FILE: tests/unit.test.tsx ===\nimport React from 'react';\nimport { render, screen, fireEvent } from '@testing-library/react';\nimport { describe, it, expect } from 'vitest';\nimport { Bm25SearchEngine } from '../src/Bm25SearchEngine';\n\ndescribe('Project 19: BM25 Probabilistic Search & Disjunctive Faceted Engine', () => {\n  it('filters documents by disjunctive domain facet and displays BM25 scores', () => {\n    render(<Bm25SearchEngine />);\n    expect(screen.getByTestId('doc-count').textContent).toBe('3');\n\n    fireEvent.click(screen.getByRole('button', { name: 'WebGL' }));\n    expect(screen.getByTestId('doc-count').textContent).toBe('1');\n    expect(screen.getByText(/Three.js WebGL PBR Shader/i)).toBeDefined();\n  });\n});\n\n// === FILE: tests/e2e.spec.ts ===\nimport { test, expect } from '@playwright/test';\n\ntest.describe('Project 19: BM25 Probabilistic Search & Disjunctive Faceted Engine \u2014 E2E & WCAG 2.2 AAA Verification', () => {\n  test('renders standalone interactive course & 3D telemetry studio without console errors', async ({ page }) => {\n    const errors: string[] = [];\n    page.on('pageerror', (err) => errors.push(err.message));\n    await page.goto('file:///Users/billyribeiro/Desktop/react-enterprise-projects/projects/19-fulltext-search-faceted-engine/index.html');\n    await expect(page.locator('h1')).toContainText(\"BM25 Probabilistic Search & Disjunctive Faceted Engine\");\n    await expect(page.locator('.step-card')).toHaveCount(5);\n    expect(errors).toEqual([]);\n  });\n});"
